export function puzzlesFor(lang: PuzzleLang): CrosswordPuzzle[] {
  return CROSSWORD_PUZZLES[lang];
}

export function getPuzzle(id: string): CrosswordPuzzle | undefined {
  return (CROSSWORD_PUZZLES.en.find((puzzle) => puzzle.id === id) ?? CROSSWORD_PUZZLES.ru.find((puzzle) => puzzle.id === id));
}
